from pathlib import Path
import re
root=Path(__file__).parent
old=(root/'question-bank-options-1.html').read_text(encoding='utf-8')
brand=re.search(r'<div class="app-brand">.*?</div>',old,re.S).group(0)
nav=re.search(r'<nav>.*?</nav>',old,re.S).group(0)
css='''*{box-sizing:border-box}body{margin:0;background:#101116;color:#f6f5ff;font-family:Arial,sans-serif}main{padding:24px;max-width:1240px;margin:auto}main>h1{font-size:27px;margin:0 0 10px}main>p{font-size:13px;color:#aba6bc;margin:0 0 23px}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.concept>h2{font-size:17px;margin:0 0 12px}.phone{background:#191a21;border:1px solid #403c4b;border-radius:24px;overflow:hidden;padding:22px 16px 85px;height:815px;position:relative}.app-brand{display:flex;align-items:center;gap:9px;font-size:17px;font-weight:700;margin-bottom:28px}.app-brand svg{width:25px;height:25px;color:#b193ff}.avatar{margin-left:auto;width:30px;height:30px;display:grid;place-items:center;border-radius:50%;background:#34294b;font-size:12px;color:#d1bbff;border:1px solid #73539e}.heading{display:flex;align-items:center;justify-content:space-between}.heading h1{font-size:28px;letter-spacing:-.035em;margin:0 0 7px}.heading p{margin:0;color:#a39aac;font-size:12px}.add{border:0;border-radius:14px;background:#9677ff;color:#fff;width:45px;height:45px;font-size:27px;box-shadow:0 5px 20px #7756d52a}.search{display:flex;align-items:center;gap:11px;background:#25252f;border:1px solid #393540;border-radius:14px;padding:14px 13px;font-size:12px;color:#a69fae;margin:23px 0 12px}.search>span:first-child{font-size:21px}.search>b{margin-left:auto;color:#c8b4ed;font-size:17px}.toolbar{display:flex;justify-content:space-between;color:#a59bb1;font-size:10px;margin:0 2px 18px}.toolbar b{color:#bba2e8;font-weight:500}.card{position:relative;margin-bottom:13px;padding:16px;border:1px solid #40394b;border-radius:17px;background:#24222e}.type{display:flex;align-items:center;justify-content:space-between;font-size:10px;color:#bca8df}.type span{display:flex;align-items:center;gap:7px}.type i{width:6px;height:6px;background:#b192f6;border-radius:50%;display:inline-block}.type button{background:none;border:none;color:#a598b7;font-size:19px;padding:0}.card h3{font-size:17px;line-height:1.45;letter-spacing:-.01em;margin:13px 0 17px;font-weight:600}.foot{display:flex;align-items:center;justify-content:space-between;color:#a194af;font-size:10px}.foot button{padding:7px 12px;border:1px solid #64527c;border-radius:8px;color:#d7c3f8;background:#352b44;font-size:10px}.line .card{background:linear-gradient(110deg,#2d253a,#23232d);border-color:#4b3c5b;padding-left:20px}.line .card:before{content:'';position:absolute;width:3px;left:0;top:23px;bottom:23px;background:#a985f3;border-radius:4px}.line .type span{background:#42304f;border-radius:20px;padding:5px 9px;font-size:9px}.line .card:nth-of-type(2):before{background:#77bfb4}.line .card:nth-of-type(2) .type span{background:#263f3c;color:#9ad6cd}.line .card:nth-of-type(3):before{background:#d3ae77}.line .card:nth-of-type(3) .type span{background:#473b2d;color:#e1c391}.soft .card{border:0;background:#292633;border-radius:20px;padding:18px}.soft .card h3{font-size:18px;line-height:1.5;margin-top:14px}.soft .foot{border-top:1px solid #494051;padding-top:12px}.soft .foot button{border:0;background:none;padding:0;color:#c7abfb}.soft .type i{width:24px;height:24px;border-radius:8px;background:#443558;color:#c7aff1;font-style:normal;text-align:center;line-height:24px}.soft .card:nth-of-type(2){background:#242e30}.soft .card:nth-of-type(2) .type i{background:#314b48;color:#a1d8cf}.soft .card:nth-of-type(3){background:#302b29}.soft .card:nth-of-type(3) .type i{background:#51402e;color:#e4c08b}.glass .card{background:linear-gradient(145deg,#34294299,#25242fcc);box-shadow:inset 0 1px 0 #ffffff07;border-color:#574168}.glass .type{color:#c4a9e2}.glass .foot button{border:0;background:#9a77ec;color:#fff;border-radius:20px;padding:8px 13px}.glass .card h3{font-size:18px}.glass .card:nth-of-type(2){background:linear-gradient(145deg,#27393688,#24272ecc);border-color:#40524e}.glass .card:nth-of-type(3){background:linear-gradient(145deg,#3c332888,#29252dcc);border-color:#51463e}.bottom-link{font-size:11px;color:#a896bf;text-align:center;margin-top:18px}nav{position:absolute;bottom:0;left:0;right:0;display:grid;grid-template-columns:repeat(5,1fr);padding:15px 8px 16px;background:#20212a;border-top:1px solid #3b3544}nav>span{display:grid;justify-items:center;gap:7px;font-size:20px;color:#9993a5}nav small{font-size:9px}nav .active{color:#b38aff}@media(max-width:760px){.gallery{grid-template-columns:1fr;max-width:390px;margin:auto}main{padding:20px 14px}}
'''
questions=[('Multiple choice','What is the capital of Japan?','4 choices','Aa'),('Matching','Match each country to its capital.','3 pairs','↔'),('Multi-blank','Water is made of ___ and ___.','2 blanks','_')]
cards=[]
for label,style in [('A · Accent edge','line'),('B · Soft surfaces','soft'),('C · Subtle glow','glass')]:
    qs=''.join(f'<article class="card"><div class="type"><span><i>{icon if style=="soft" else ""}</i>{kind}</span><button>⋯</button></div><h3>{q}</h3><div class="foot"><span>{detail} · Edited today</span><button>Edit ↗</button></div></article>' for kind,q,detail,icon in questions)
    cards.append(f'<section class="concept"><h2>{label}</h2><div class="phone {style}">{brand}<div class="heading"><div><h1>Questions</h1><p>Your library · 17 questions</p></div><button class="add">＋</button></div><div class="search"><span>⌕</span><span>Search your questions</span><b>☷</b></div><div class="toolbar"><span>All questions · Newest first ▾</span><b>Advanced</b></div>{qs}<div class="bottom-link">Import questions ↗</div>{nav}</div></section>')
(root/'question-bank-polished.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RecallFlow · polished question lists</title><style>{css}</style></head><body><main><h1>One question list. Three visual styles.</h1><p>Mobile design previews · full question text, quieter controls and clearer spacing.</p><div class="gallery">{"".join(cards)}</div></main></body></html>',encoding='utf-8')
